<section class="shipment-summary"><div class="summary-copy"><span class="eyebrow">Resumo da remessa</span></div><div id="component-summary" class="component-summary" aria-live="polite"></div><div class="summary-indicators"><div class="summary-pill"><strong id="sample-count">0</strong><span>amostra(s)</span></div><div class="summary-pill"><strong id="box-count">0</strong><span>caixa(s)</span></div></div></section>
